// Минимальный рабочий код для вашей структуры
const recipes = $input.first().json.data.recipes;

return recipes.map((recipe, index) => ({
  json: recipe,
  pairedItem: { item: index }
}));

// Prepare recipe text: собираем полный текст из структурированного рецепта
// и сопоставляем с полным текстом из второго файла

function toTranslit(text) {
  const map = {
    'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'e',
    'ж':'zh','з':'z','и':'i','й':'j','к':'k','л':'l','м':'m',
    'н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u',
    'ф':'f','х':'h','ц':'c','ч':'ch','ш':'sh','щ':'shch',
    'ъ':'','ы':'y','ь':'','э':'e','ю':'yu','я':'ya'
  };
  return text.toLowerCase().split('').map(char => map[char] || char).join('');
}

function calculateSimilarity(str1, str2) {
  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;
  if (longer.length === 0) return 1.0;
  let matches = 0;
  for (let i = 0; i < Math.min(shorter.length, longer.length); i++) {
    if (shorter[i] === longer[i]) matches++;
  }
  return matches / longer.length;
}

const recipe = $('Loop Over Items').first().json;
const recipesArray = $input.first().json.data.recipes_full_text;

const recipeId = (recipe.id || '').trim();
const recipeTranslit = toTranslit(recipeId).replace(/_+/g, '_');

let textRecipe = null;
let bestMatchScore = 0;
let bestMatchRecipe = null;

for (const r of recipesArray) {
  if (!r.id) continue;
  const rId = r.id.trim().toLowerCase();
  const rTranslit = toTranslit(rId).replace(/_+/g, '_');

  if (rTranslit === recipeTranslit) {
    textRecipe = r;
    break;
  }

  if (rTranslit.includes(recipeTranslit) || recipeTranslit.includes(rTranslit)) {
    const matchLength = Math.min(rTranslit.length, recipeTranslit.length);
    if (matchLength > bestMatchScore) {
      bestMatchScore = matchLength;
      bestMatchRecipe = r;
    }
  }

  const similarity = calculateSimilarity(rTranslit, recipeTranslit);
  if (similarity > 0.8 && similarity > bestMatchScore) {
    bestMatchScore = similarity;
    bestMatchRecipe = r;
  }
}

if (!textRecipe && bestMatchRecipe) {
  textRecipe = bestMatchRecipe;
}

const embeddingText = textRecipe?.full_text || `${recipe.name || ''} ${recipe.category || ''}`;

// Извлекаем метаданные из структурированного рецепта
let volume = null;
let strength = null;
if (recipe.preparation && recipe.preparation.description) {
  const desc = recipe.preparation.description;
  const volumeMatch = desc.match(/(\d+(?:\.\d+)?)\s*(дкл|л)/i);
  const strengthMatch = desc.match(/(\d+(?:\.\d+)?)\s*°?\s*(?:по\s+)?Траллесу/i);
  if (volumeMatch) volume = parseFloat(volumeMatch[1]);
  if (strengthMatch) strength = parseFloat(strengthMatch[1]);
}

return [{
  json: {
    embed_text: embeddingText,
    recipe_data: {
      id: recipe.id || 'unknown',
      name: recipe.name || 'Без названия',
      category: recipe.category || '',
      year: recipe.year || null,
      quality: recipe.quality || '',
      volume: volume,
      strength: strength,
      infusion_time: recipe.infusion_time || '',
      ingredients_count: (recipe.ingredients || []).length + (recipe.infusion_ingredients || []).length,
      process_steps: (recipe.process || []).length,
      full_text: embeddingText,
      text_found: !!textRecipe
    }
  }
}];

// Combining vectors: BGE-M3 dense + sparse → Qdrant point
const response = $input.last().json;
const recipe = $('Prepare recipe text').first().json.recipe_data;

const dense = response.results[0].dense;
const sparse = response.results[0].sparse;

console.log(`Рецепт: ${recipe.name}`);
console.log(`Dense: ${dense.length} dims, Sparse: ${sparse.indices.length} tokens`);

const pointId = Math.abs(Date.now() % 1000000000 + Math.floor(Math.random() * 10000));

const point = {
  id: pointId,
  vector: {
    dense: dense,
    sparse: sparse
  },
  payload: {
    recipe_id: recipe.id,
    recipe_name: recipe.name,
    category: recipe.category,
    year: recipe.year,
    quality: recipe.quality,
    volume: recipe.volume,
    strength: recipe.strength,
    infusion_time: recipe.infusion_time,
    ingredients_count: recipe.ingredients_count,
    process_steps: recipe.process_steps,
    content: recipe.full_text,
    full_text: recipe.full_text,
    content_length: recipe.full_text?.length || 0,
    name_lower: recipe.name?.toLowerCase() || '',
    text_found: recipe.text_found,
    created_at: new Date().toISOString(),
    vector_dimension: dense.length,
    sparse_token_count: sparse.indices.length,
    source: 'stritter_historical_recipes'
  }
};

console.log(`✅ Point создан: ID=${pointId}, рецепт "${recipe.name}"`);

return [{ json: { points: [point] } }];
